import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { ubicacionesData } from "../data/ubicacionesData";

/* ======================================================
   COMPONENTE FUSION: Combina Administrativas y Ubicaciones
   ====================================================== */
export default function Nfusion() {
  const navigate = useNavigate();
  const chatEndRef = useRef(null);

  // ====================== Estado ======================
  const [activeModule, setActiveModule] = useState(null); // "administrativas" | "ubicaciones"
  const [messages, setMessages] = useState([]);
  const [inputValue, setInputValue] = useState("");
  const [showMoreOptions, setShowMoreOptions] = useState(false); // Para Administrativas
  const [showMap, setShowMap] = useState(false); // Para Ubicaciones
  const [animateMap, setAnimateMap] = useState(false); // Para animación mapa

  // ================== Opciones Administrativas ==================
  const predefinedOptions = [
    { img: "/item-chat.png", text: "Kardex" },
    { img: "/item-chat.png", text: "Constancia" },
    { img: "/item-chat.png", text: "Titulacion" },
    { img: "/item-chat.png", text: "Creditos" },
    { img: "/item-chat.png", text: "Mas opciones..." },
  ];

  const additionalOptions = [
    { img: "/item-chat.png", text: "Historial Academico" },
    { img: "/item-chat.png", text: "Pagos y Finanzas" },
    { img: "/item-chat.png", text: "Horarios" },
  ];

  // ================== Efectos ==================
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  useEffect(() => {
    if (showMap) document.body.classList.add("map-open");
    else document.body.classList.remove("map-open");
  }, [showMap]);

  // ================== Funciones comunes ==================
  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSendMessage();
  };

  const goBackToMenu = () => {
    setActiveModule(null);
    setMessages([]);
    setInputValue("");
    setShowMoreOptions(false);
    setShowMap(false);
  };

  // ================== Funciones Administrativas ==================
  const handleOptionClick = (option) => {
    const userMessage = { type: "user", content: option, timestamp: new Date() };

    const botInfo = {
      type: "bot",
      content: `Para el proceso de ${option.toLowerCase()} se tiene que hacer lo siguiente:

1.- Ingresa al SIM con tu número de control y contraseña.
2.- Dirígete al módulo correspondiente.
3.- Ahí te aparecerá una tabla con las opciones relacionadas, selecciona la que necesites.
4.- Por último, sigue las instrucciones mostradas.`,
      timestamp: new Date(),
    };

    const botActions = {
      type: "bot",
      content:
        'Si quiere cambiar de proceso, presione el botón de opciones en el área de texto.',
      timestamp: new Date(),
    };

    if (option === "Mas opciones...") {
      setShowMoreOptions(true);
      setMessages((prev) => [
        ...prev,
        userMessage,
        { type: "bot", content: "moreOptions", timestamp: new Date() },
        {
          type: "bot",
          content:
            "Si no se encuentra la opción que usted busca, favor de escribirla en el chat.",
          timestamp: new Date(),
        },
      ]);
    } else {
      setMessages((prev) => [...prev, userMessage, botInfo, botActions]);
    }
  };

  const simulateAdminResponse = (userInput) => {
    const input = userInput.toLowerCase();
    const botResponse = { type: "bot", content: "", timestamp: new Date() };

    if (input.includes("evaluacion") || input.includes("profesor")) {
      botResponse.content = `Para el proceso de evaluación de docentes se tiene que hacer lo siguiente:

1.- Ingresa al SIM con tu número de control y contraseña.
2.- Dirígete al módulo de evaluaciones y encuestas.
3.- Ahí te aparecerá una tabla con todas las evaluaciones posibles, selecciona la que necesites.
4.- Por último, contesta todas las preguntas.`;
      setMessages((prev) => [
        ...prev,
        botResponse,
        {
          type: "bot",
          content:
            'Si quiere cambiar de proceso, presione el botón de opciones en el área de texto.',
          timestamp: new Date(),
        },
      ]);
      return;
    }

    if (input.includes("kardex")) botResponse.content = `El Kardex es un documento que muestra tu historial académico completo.`;
    else if (input.includes("constancia")) botResponse.content = `La constancia de estudios se solicita en servicios escolares.`;
    else if (input.includes("titulacion")) botResponse.content = `El proceso de titulación implica completar créditos y requisitos.`;
    else if (input.includes("credito")) botResponse.content = `Los créditos complementarios se registran en actividades culturales o académicas.`;
    else if (input.includes("historial")) botResponse.content = `El historial académico se descarga desde el portal del SIM.`;
    else if (input.includes("pago")) botResponse.content = `Los pagos se realizan en caja o por transferencia.`;
    else if (input.includes("horario")) botResponse.content = `Tu horario actual se encuentra en el portal del SIM.`;
    else botResponse.content = `Has escrito: "${userInput}". ¿Podrías darme más detalles?`;

    setMessages((prev) => [...prev, botResponse]);
  };

  const handleSendMessageAdmin = () => {
    if (!inputValue.trim()) return;
    const newMessages = [...messages, { type: "user", content: inputValue, timestamp: new Date() }];
    setMessages(newMessages);
    setInputValue("");
    setTimeout(() => simulateAdminResponse(inputValue), 500);
  };

  // ================== Funciones Ubicaciones ==================
  const generateLocationResponse = (userInput) => {
    const input = userInput.toUpperCase();
    const ubicacion = ubicacionesData.find((u) => u.id === input);

    if (ubicacion) {
      return [
        { type: "bot", content: ubicacion.texto },
        { type: "bot", content: "building_image", buildingImage: ubicacion.imagen },
        { type: "bot", content: "Si ocupa saber otra ubicación, escríbela o consulta el mapa." },
      ];
    }
    return [{ type: "bot", content: "Lo siento, no tengo información sobre esa ubicación." }];
  };

  const handleSendMessageUb = () => {
    if (!inputValue.trim()) return;
    const userMessage = { type: "user-ub", content: inputValue };
    const botResponse = generateLocationResponse(inputValue);
    setMessages((prev) => [...prev, userMessage, ...botResponse]);
    setInputValue("");
  };

  const toggleMap = () => {
    if (showMap) {
      setAnimateMap(false);
      setTimeout(() => setShowMap(false), 300);
    } else {
      setShowMap(true);
      setTimeout(() => setAnimateMap(true), 10);
    }
  };

  const handleMapButtonClick = (id) => {
    const botResponse = generateLocationResponse(id);
    const userMessage = { type: "user-ub", content: id };
    setMessages((prev) => [...prev, userMessage, ...botResponse]);
  };

  // ================== Función común de envío ==================
  const handleSendMessage = () => {
    if (activeModule === "administrativas") handleSendMessageAdmin();
    else if (activeModule === "ubicaciones") handleSendMessageUb();
  };

  // ================== Render ==================
  if (!activeModule) {
    // Pantalla inicial de selección de módulo
    return (
      <div className="fusion-container">
        <h1>TalkinPon</h1>
        <div className="fusion-selection">
          <button onClick={() => { setActiveModule("administrativas"); setMessages([{ type: "bot", content: "options", timestamp: new Date() }]); }}>
            Procesos Administrativos
          </button>
          <button onClick={() => { setActiveModule("ubicaciones"); setMessages([{ type: "bot", content: "¿Qué edificio o salón te gustaría saber su ubicación?" }]); }}>
            Ubicaciones del Campus
          </button>
        </div>
      </div>
    );
  }

  // Render del chat según módulo activo
  return (
    <div className={activeModule === "administrativas" ? "procesos-container" : "ubicaciones-container"}>
      {/* Header */}
      <header className={activeModule === "administrativas" ? "procesos-header" : "ubicaciones-header"}>
        <div className="procesos-header-left">
          <button className={activeModule === "administrativas" ? "procesos-name-button" : "ubicaciones-name-button"} onClick={goBackToMenu}>
            <i className="bi bi-chevron-double-left"></i>
          </button>
          <h1>TalkinPon</h1>
        </div>
        <div className={activeModule === "administrativas" ? "procesos-title-logo" : "ubicaciones-title-logo"}>
          <h2>{activeModule === "administrativas" ? "Procesos Administrativos" : "Ubicaciones"}</h2>
        </div>
        <div className="ubicaciones-heade-logo">
          {activeModule === "ubicaciones" && (
            <button onClick={toggleMap} className="ubicaciones-toggle-btn" title="Mostrar mapa">
              <i className="bi bi-map-fill"></i>
            </button>
          )}
        </div>
        <div className={activeModule === "administrativas" ? "procesos-heade-logo" : "ubicaciones-heade-logo"}>
          <img src="/logo-app.png" alt="Logo" />
        </div>
      </header>

      {/* Chat */}
      <div className={activeModule === "administrativas" ? "procesos-chat-area" : "main-content"}>
        <div className={activeModule === "administrativas" ? null : "chat-area-ub"}>
          {messages.map((message, idx) => (
            <div
              key={idx}
              className={activeModule === "administrativas" ? `procesos-chat-message ${message.type}` : `message-row-ub ${message.type}`}
            >
              <div className={activeModule === "administrativas" ? "procesos-avatar" : null}>
                <img
                  src={message.type === "bot" ? "/logo-app.png" : "/img-user.png"}
                  alt={message.type === "bot" ? "Bot" : "User"}
                  className={activeModule === "ubicaciones" ? "avatar-ub" : ""}
                />
              </div>

              <div className={activeModule === "administrativas" ? "procesos-message-with-actions" : "message-with-actions"}>
                {activeModule === "administrativas" && (message.content === "options" || message.content === "moreOptions") ? (
                  <div className="procesos-options-box">
                    <h3>{message.content === "options" ? "Elige una opción:" : "Más opciones disponibles:"}</h3>
                    {(message.content === "options" ? predefinedOptions : additionalOptions).map((option, idx) => (
                      <button key={idx} onClick={() => handleOptionClick(option.text)}>
                        <img src={option.img} alt={option.text} className="procesos-option-img" />
                        <span>{option.text}</span>
                      </button>
                    ))}
                  </div>
                ) : activeModule === "administrativas" ? (
                  <div className={`procesos-message-box ${message.type}`}>
                    <p>{message.content}</p>
                  </div>
                ) : (
                  <div className="message-box-ub">
                    {message.content === "building_image" ? (
                      <img src={message.buildingImage} alt="Edificio" className="building-image" />
                    ) : (
                      <p>{message.content}</p>
                    )}
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={chatEndRef}></div>
        </div>
      </div>

      {/* Input */}
      <div className={activeModule === "administrativas" ? "procesos-input-area border-top" : "ubicaciones-input-area border-top"}>
        <div className={activeModule === "administrativas" ? "procesos-input-group" : "ubicaciones-input-group"}>
          <input
            type="text"
            className={activeModule === "administrativas" ? "procesos-form-control" : "ubicaciones-form-control"}
            placeholder="¿Qué te gustaría saber ...?"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyPress={handleKeyPress}
          />
          <button className={activeModule === "administrativas" ? "procesos-btn" : "ubicaciones-btn"} onClick={handleSendMessage}>
            <i className="bi bi-send-fill"></i>
          </button>
        </div>
        {activeModule === "administrativas" && (
          <div className="procesos-div-cambio">
            <button className="procesos-btn-cambio" onClick={() => setShowMoreOptions(true)}>
              <i className="bi bi-menu-up"></i>
            </button>
          </div>
        )}
      </div>

      {/* Mapa */}
      {activeModule === "ubicaciones" && showMap && (
        <>
          <div className="map-overlay"></div>
          <div className={`map-area ${animateMap ? "map-open" : "map-close"}`}>
            <div className="map-header">
              <h3>Mapa del Campus</h3>
              <button
                onClick={() => {
                  setAnimateMap(false);
                  setTimeout(() => setShowMap(false), 300);
                }}
                className="close-map-btn"
              >
                ✕
              </button>
            </div>

            <div className="map-container">
              <img src="/mapa_tec.png" alt="Mapa Campus" className="campus-map" />
              {ubicacionesData.map((u) => (
                <button
                  key={u.id}
                  className="map-button"
                  style={{ top: u.posicionMapa.top, left: u.posicionMapa.left }}
                  onClick={() => handleMapButtonClick(u.id)}
                >
                  {u.id}
                </button>
              ))}
            </div>

            <p className="map-caption">Mapa interactivo del campus universitario</p>
          </div>
        </>
      )}
    </div>
  );
}
